-- EventCrowd PostgreSQL relational core (all transactions authoritative here)
BEGIN;
-- PostgreSQL 13+ provides gen_random_uuid() natively.
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles (id smallserial PRIMARY KEY,name text NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id smallint NOT NULL REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS venues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,address text NOT NULL,capacity integer NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS zones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venues(id),name text NOT NULL,area_m2 numeric(12,2) NOT NULL CHECK(area_m2>0),UNIQUE(venue_id,name));
CREATE TABLE IF NOT EXISTS gates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venues(id),name text NOT NULL,UNIQUE(venue_id,name));
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),venue_id uuid NOT NULL REFERENCES venues(id),created_by uuid REFERENCES users(id),name text NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','LIVE','COMPLETED')),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS event_zones(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),zone_id uuid NOT NULL REFERENCES zones(id),capacity integer NOT NULL CHECK(capacity>0),warning_pct numeric(5,2) NOT NULL DEFAULT 80 CHECK(warning_pct BETWEEN 0 AND 100),critical_pct numeric(5,2) NOT NULL DEFAULT 95 CHECK(critical_pct BETWEEN 0 AND 100),CHECK(warning_pct<critical_pct),UNIQUE(event_id,zone_id));
CREATE TABLE IF NOT EXISTS event_gates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),gate_id uuid NOT NULL REFERENCES gates(id),is_open boolean NOT NULL DEFAULT true,UNIQUE(event_id,gate_id));
CREATE TABLE IF NOT EXISTS event_gate_zones(event_gate_id uuid NOT NULL REFERENCES event_gates(id),event_zone_id uuid NOT NULL REFERENCES event_zones(id),PRIMARY KEY(event_gate_id,event_zone_id));
CREATE TABLE IF NOT EXISTS devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),gate_id uuid REFERENCES gates(id),device_type text NOT NULL,device_name text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE IF NOT EXISTS attendees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id),emergency_contact text);
CREATE TABLE IF NOT EXISTS ticket_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),name text NOT NULL,price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price>=0),reentry_allowed boolean NOT NULL DEFAULT false,UNIQUE(event_id,name));
CREATE TABLE IF NOT EXISTS registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),attendee_id uuid NOT NULL REFERENCES attendees(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,attendee_id));
CREATE TABLE IF NOT EXISTS tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),registration_id uuid NOT NULL UNIQUE REFERENCES registrations(id),ticket_type_id uuid NOT NULL REFERENCES ticket_types(id),qr_token_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'VALID' CHECK(status IN('VALID','REVOKED')));
CREATE TABLE IF NOT EXISTS ticket_zone_access(ticket_type_id uuid NOT NULL REFERENCES ticket_types(id),event_zone_id uuid NOT NULL REFERENCES event_zones(id),PRIMARY KEY(ticket_type_id,event_zone_id));
CREATE TABLE IF NOT EXISTS scan_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid REFERENCES tickets(id),event_gate_id uuid NOT NULL REFERENCES event_gates(id),device_id uuid REFERENCES devices(id),scan_type text NOT NULL CHECK(scan_type IN('ENTRY','EXIT')),result text NOT NULL CHECK(result IN('ACCEPTED','REJECTED')),reason text,scanned_at timestamptz NOT NULL DEFAULT now(),idempotency_key text NOT NULL UNIQUE,request_fingerprint text NOT NULL);
CREATE TABLE IF NOT EXISTS admission_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES tickets(id),entry_scan_id uuid NOT NULL UNIQUE REFERENCES scan_attempts(id),exit_scan_id uuid UNIQUE REFERENCES scan_attempts(id),entered_at timestamptz NOT NULL DEFAULT now(),exited_at timestamptz,CHECK(exited_at IS NULL OR exited_at>=entered_at));
CREATE UNIQUE INDEX IF NOT EXISTS uq_active_ticket_admission ON admission_sessions(ticket_id) WHERE exited_at IS NULL;
CREATE TABLE IF NOT EXISTS zone_states(event_zone_id uuid PRIMARY KEY REFERENCES event_zones(id),estimated_people integer NOT NULL CHECK(estimated_people>=0),source_type text NOT NULL,observed_at timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gate_queue_states(event_gate_id uuid PRIMARY KEY REFERENCES event_gates(id),people_waiting integer NOT NULL CHECK(people_waiting>=0),processing_per_min numeric(9,2) CHECK(processing_per_min>=0),observed_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS crowd_alerts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),event_zone_id uuid REFERENCES event_zones(id),event_gate_id uuid REFERENCES event_gates(id),severity text NOT NULL CHECK(severity IN('INFO','WARNING','CRITICAL')),message text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','RESOLVED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS staff_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL UNIQUE REFERENCES users(id),designation text NOT NULL);
CREATE TABLE IF NOT EXISTS staff_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),staff_id uuid NOT NULL REFERENCES staff_profiles(id),event_id uuid NOT NULL REFERENCES events(id),event_zone_id uuid REFERENCES event_zones(id),event_gate_id uuid REFERENCES event_gates(id),shift_start timestamptz NOT NULL,shift_end timestamptz NOT NULL,CHECK(shift_end>shift_start));
CREATE TABLE IF NOT EXISTS incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),event_zone_id uuid REFERENCES event_zones(id),reported_by uuid REFERENCES users(id),category text NOT NULL,severity text NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),description text NOT NULL,status text NOT NULL DEFAULT 'OPEN' CHECK(status IN('OPEN','INVESTIGATING','RESOLVED')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incident_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL REFERENCES incidents(id),staff_id uuid REFERENCES staff_profiles(id),action_taken text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,user_id uuid REFERENCES users(id),action text NOT NULL,entity text NOT NULL,entity_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_type text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,retries integer NOT NULL DEFAULT 0 CHECK(retries>=0));
CREATE INDEX IF NOT EXISTS idx_scans_gate_time ON scan_attempts(event_gate_id,scanned_at DESC);
CREATE INDEX IF NOT EXISTS idx_incidents_event_time ON incidents(event_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_event_time ON crowd_alerts(event_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_outbox_pending ON outbox_events(created_at) WHERE delivered_at IS NULL;
CREATE OR REPLACE VIEW v_event_attendance AS SELECT e.id AS event_id,e.name,COUNT(s.id) FILTER(WHERE s.exited_at IS NULL) AS currently_inside,COUNT(s.id) AS accepted_entries FROM events e LEFT JOIN registrations r ON r.event_id=e.id LEFT JOIN tickets t ON t.registration_id=r.id LEFT JOIN admission_sessions s ON s.ticket_id=t.id GROUP BY e.id;
CREATE OR REPLACE VIEW v_zone_pressure AS SELECT ez.event_id,ez.id AS event_zone_id,z.name,ez.capacity,COALESCE(zs.estimated_people,0) AS estimated_people,ROUND(COALESCE(zs.estimated_people,0)*100.0/ez.capacity,2) AS occupancy_pct FROM event_zones ez JOIN zones z ON z.id=ez.zone_id LEFT JOIN zone_states zs ON zs.event_zone_id=ez.id;
CREATE OR REPLACE FUNCTION audit_incident_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO audit_logs(action,entity,entity_id) VALUES (TG_OP,'incidents',NEW.id::text);RETURN NEW;END $$;
DROP TRIGGER IF EXISTS trg_incident_audit ON incidents;
CREATE TRIGGER trg_incident_audit AFTER INSERT OR UPDATE ON incidents FOR EACH ROW EXECUTE FUNCTION audit_incident_change();
CREATE OR REPLACE FUNCTION event_attendance_count(p_event uuid) RETURNS bigint LANGUAGE sql STABLE AS $$ SELECT COUNT(*) FROM admission_sessions s JOIN tickets t ON t.id=s.ticket_id JOIN registrations r ON r.id=t.registration_id WHERE r.event_id=p_event AND s.exited_at IS NULL $$;
COMMIT;
